        if overlap:
            cell = sorted(overlap)[0]
            raise ValueError(
                f"{context} adds and removes the same cell {list(cell)}"
            )
        changes.append(
            {
                "type": "map_change",
                "tick": tick,
                "sequence": sequence,
                "added": [list(cell) for cell in added],
                "removed": [list(cell) for cell in removed],
            }
        )
        last_tick = tick
        last_sequence = sequence
    return changes

